async function getSubscribers() {
  const url = SUPABASE_URL + '/rest/v1/alert_subscribers?product=eq.vigilante&active=eq.true&select=phone';
  try {
    const data = await http({ method: 'GET', url, headers: { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY } });
    return Array.isArray(data) ? data : [];
  } catch (e) { return []; }
}

// 1. Parse webhook from Uptime Kuma
